-- Biologie NS3 ch.1 muscles : énoncés remis au texte du Larousse (validé par l'utilisateur)
BEGIN;
CREATE TEMP TABLE maj (ancien TEXT, enonce TEXT, explication TEXT, choix JSONB) ON COMMIT DROP;
WITH u AS (
  UPDATE questions q SET enonce = m.enonce, explication = m.explication, choix = m.choix
  FROM maj m, chapitres c
  WHERE c.id = q.chapitre_id AND c.matiere_id = 11 AND c.titre = 'Les muscles : types, structure et propriétés' AND q.enonce = m.ancien
  RETURNING q.id)
SELECT COUNT(*) AS questions_modifiees FROM u;
COMMIT;
